mapper.select:
SELECT COUNT(*)
FROM user_coupon
WHERE user_id = #{userId}
  AND coupon_id = #{couponId}

SELECT uc.id AS user_coupon_id, uc.coupon_id, c.coupon_name, c.type, c.threshold_amount, c.discount_amount, uc.coupon_status, uc.receive_time, uc.expire_time, uc.use_time, uc.order_no FROM user_coupon uc INNER JOIN coupon c ON c.id = uc.coupon_id WHERE uc.user_id = #{userId}
AND uc.coupon_status = #{status}
ORDER BY uc.receive_time DESC
